SELECT CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, s.country, MAX(p.stock_qty) AS max_stock_qty FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END, s.country ORDER BY max_stock_qty ASC;
